#!/usr/bin/env node
/**
 * Writes client-registry.generated.ts from the folders under src/invitations/clients/.
 * `--check` only compares and exits 1 when the generated file is stale.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import {
	clientInvitationDir,
	listClientInvitationSlugs,
} from '../../shared/invitation-definition-files.ts';

export const CLIENT_REGISTRY_FILE = 'scripts/provision/invitations/client-registry.generated.ts';

export function renderClientRegistry(slugs: readonly string[]): string {
	const imports = slugs.map(
		(slug, index) =>
			`import invitation${index} from '../../../${clientInvitationDir(slug)}/invitation.ts';`,
	);
	const list = slugs.length
		? ['[', ...slugs.map((_, index) => `\tinvitation${index},`), '];']
		: ['[];'];
	return [
		'// Generated by `pnpm invitation:registry` from src/invitations/clients/*/invitation.ts.',
		'// Do not edit by hand.',
		"import type { InvitationDefinition } from './invitation-definition.ts';",
		...imports,
		'',
		`export const CLIENT_INVITATION_DEFINITIONS: readonly InvitationDefinition[] = ${list[0]}`,
		...list.slice(1),
		'',
	].join('\n');
}

function main(): void {
	const root = process.cwd();
	const target = path.join(root, CLIENT_REGISTRY_FILE);
	const expected = renderClientRegistry(listClientInvitationSlugs(root));
	const current = readFileSync(target, 'utf8').replaceAll('\r\n', '\n');
	if (process.argv.includes('--check')) {
		if (current !== expected) {
			console.error(`${CLIENT_REGISTRY_FILE} is stale. Run pnpm invitation:registry.`);
			process.exitCode = 1;
		}
		return;
	}
	if (current !== expected) writeFileSync(target, expected);
	console.log(`${CLIENT_REGISTRY_FILE}: ${expected === current ? 'up to date' : 'written'}.`);
}

if (/generate-client-registry\.(ts|js|mjs|cjs)$/.test(process.argv[1] ?? '')) main();
